# 代码审查源文件


## backend\src\db\connection.js

const Database = require('better-sqlite3');
const path = require('path');

// 数据库文件路径
const dbPath = path.join(__dirname, '../../data/monopoly.db');

// 初始化数据库
const initializeDatabase = () => {
  const db = new Database(dbPath);

  // 启用外键约束
  db.pragma('foreign_keys = ON');

  // 创建用户表
  db.exec(`
    CREATE TABLE IF NOT EXISTS users (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      username TEXT UNIQUE NOT NULL,
      password_hash TEXT NOT NULL,
      email TEXT UNIQUE NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      updated_at DATETIME DEFAULT CURRENT_TIMESTAMP
    )
  `);

  // 创建房间表
  db.exec(`
    CREATE TABLE IF NOT EXISTS rooms (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      max_players INTEGER DEFAULT 4,
      status TEXT DEFAULT 'waiting',
      created_by INTEGER NOT NULL,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (created_by) REFERENCES users(id)
    )
  `);

  // 创建玩家表
  db.exec(`
    CREATE TABLE IF NOT EXISTS players (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      user_id INTEGER NOT NULL,
      room_id INTEGER NOT NULL,
      position INTEGER DEFAULT 0,
      money INTEGER DEFAULT 1500,
      is_ready BOOLEAN DEFAULT FALSE,
      is_bankrupt BOOLEAN DEFAULT FALSE,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (user_id) REFERENCES users(id),
      FOREIGN KEY (room_id) REFERENCES rooms(id),
      UNIQUE(user_id, room_id)
    )
  `);

  // 创建地产表
  db.exec(`
    CREATE TABLE IF NOT EXISTS properties (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      name TEXT NOT NULL,
      price INTEGER NOT NULL,
      rent INTEGER NOT NULL,
      position INTEGER NOT NULL,
      color TEXT NOT NULL,
      owner_id INTEGER,
      houses INTEGER DEFAULT 0,
      hotel BOOLEAN DEFAULT FALSE,
      FOREIGN KEY (owner_id) REFERENCES players(id)
    )
  `);

  // 创建卡牌表
  db.exec(`
    CREATE TABLE IF NOT EXISTS cards (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      type TEXT NOT NULL,
      description TEXT NOT NULL,
      effect_value INTEGER DEFAULT 0,
      effect_target TEXT DEFAULT 'self',
      position INTEGER NOT NULL
    )
  `);

  // 创建游戏记录表
  db.exec(`
    CREATE TABLE IF NOT EXISTS game_logs (
      id INTEGER PRIMARY KEY AUTOINCREMENT,
      room_id INTEGER NOT NULL,
      player_id INTEGER,
      action TEXT NOT NULL,
      details TEXT,
      created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
      FOREIGN KEY (room_id) REFERENCES rooms(id),
      FOREIGN KEY (player_id) REFERENCES players(id)
    )
  `);

  // 创建索引
  db.exec(`CREATE INDEX IF NOT EXISTS idx_users_username ON users(username)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_users_email ON users(email)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_rooms_status ON rooms(status)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_players_room_id ON players(room_id)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_properties_owner_id ON properties(owner_id)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_cards_type ON cards(type)`);
  db.exec(`CREATE INDEX IF NOT EXISTS idx_game_logs_room_id ON game_logs(room_id)`);

  return db;
};

// 初始化数据库连接
let db = initializeDatabase();

// 导出数据库连接和初始化函数
module.exports = { db, initializeDatabase };
```

## backend\src\middleware\auth.js

const jwt = require('jsonwebtoken');
const { db } = require('../db/connection');

// JWT认证中间件
const authMiddleware = (req, res, next) => {
  // 从请求头获取token
  const authHeader = req.headers.authorization;

  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({
      code: 401,
      message: '认证失败',
      errors: ['未提供认证令牌']
    });
  }

  // 提取token
  const token = authHeader.split(' ')[1];

  try {
    // 验证token
    const decoded = jwt.verify(token, process.env.JWT_SECRET || 'your-secret-key');

    // 将用户信息添加到请求对象
    req.user = decoded;

    // 继续处理请求
    next();
  } catch (error) {
    // token无效或过期
    return res.status(401).json({
      code: 401,
      message: '认证失败',
      errors: ['无效的认证令牌或令牌已过期']
    });
  }
};

// 可选：检查用户是否存在的中间件
const checkUserExists = async (req, res, next) => {
  try {
    const userId = req.user.userId;

    // 检查用户是否存在
    const user = await db.get('SELECT id FROM users WHERE id = ?', [userId]);

    if (!user) {
      return res.status(404).json({
        code: 404,
        message: '用户不存在',
        errors: ['找不到指定的用户']
      });
    }

    next();
  } catch (error) {
    console.error('检查用户存在性错误:', error);
    return res.status(500).json({
      code: 500,
      message: '服务器内部错误',
      errors: ['验证用户存在性时发生错误']
    });
  }
};

module.exports = authMiddleware;
module.exports.checkUserExists = checkUserExists;
```

## backend\src\models\Card.js

const { db } = require('../db/connection');

class Card {
  static async create(cardData) {
    const { type, title, description, action, value } = cardData;
    const sql = `
      INSERT INTO cards (type, title, description, action, value, created_at)
      VALUES (?, ?, ?, ?, ?, datetime('now'))
    `;
    const result = db.prepare(sql).run(type, title, description, action, value);
    return this.findById(result.lastInsertRowid);
  }

  static async findById(id) {
    const sql = 'SELECT * FROM cards WHERE id = ?';
    const card = db.prepare(sql).get(id);
    if (!card) return null;

    return {
      id: card.id,
      type: card.type,
      title: card.title,
      description: card.description,
      action: card.action,
      value: card.value,
      createdAt: card.created_at
    };
  }

  static async findByType(type) {
    const sql = 'SELECT * FROM cards WHERE type = ? ORDER BY RANDOM() LIMIT 1';
    const card = db.prepare(sql).get(type);
    if (!card) return null;

    return {
      id: card.id,
      type: card.type,
      title: card.title,
      description: card.description,
      action: card.action,
      value: card.value,
      createdAt: card.created_at
    };
  }

  static async findAll() {
    const sql = 'SELECT * FROM cards ORDER BY type, id';
    const cards = db.prepare(sql).all();
    return cards.map(card => ({
      id: card.id,
      type: card.type,
      title: card.title,
      description: card.description,
      action: card.action,
      value: card.value,
      createdAt: card.created_at
    }));
  }

  static async update(id, cardData) {
    const { type, title, description, action, value } = cardData;
