      // 更新房屋数量
      await Property.updateHouseCount(propertyId, property.houses + houseCount, transaction);

      // 更新租金
      const newRent = property.rent * (1 + 0.5 * houseCount);
      await Property.updateRent(propertyId, newRent, transaction);

      // 提交事务
