      // 获取更新后的玩家信息
      const updatedPlayer = await Player.getById(player.id);

      res.json({
        code: 200,
        data: {
          propertyId,
          houseCount: property.houses + houseCount,
          cost: totalCost,
          remainingMoney: updatedPlayer.money,
          newRent
        },
        message: '房屋建设成功'
      });
    } catch (error) {
      await transaction.rollback();
      throw error;
    }
  } catch (error) {
