import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../hooks/useAuth';
import { useSocket } from '../hooks/useSocket';
import apiClient from '../utils/apiClient';
import { validateRoomName } from '../utils/validation';

const LobbyPage = () => {
  const { user, logout } = useAuth();
  const navigate = useNavigate();
  const socket = useSocket();

  // 状态管理
  const [rooms, setRooms] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [showCreateModal, setShowCreateModal] = useState(false);
  const [newRoomName, setNewRoomName] = useState('');
  const [newRoomMaxPlayers, setNewRoomMaxPlayers] = useState(4);
  const [creatingRoom, setCreatingRoom] = useState(false);
  const [filter, setFilter] = useState('waiting');
  const [pagination, setPagination] = useState({
    limit: 10,
    offset: 0,
    total: 0
  });

  // 检查用户是否登录
  useEffect(() => {
    if (!user) {
      navigate('/login');
    }
  }, [user, navigate]);

  // 获取房间列表
  const fetchRooms = async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        status: filter,
        limit: pagination.limit,
        offset: pagination.offset
      });

      const response = await apiClient.get(`/api/rooms?${params}`);

      if (response.code === 200) {
        setRooms(response.data.rooms);
        setPagination(prev => ({
          ...prev,
          total: response.data.total
        }));
      } else {
        setError(response.message || '获取房间列表失败');
      }
    } catch (err) {
      console.error('获取房间列表失败:', err);
      setError('获取房间列表失败，请稍后重试');
    } finally {
      setLoading(false);
    }
  };

  // 初始化时获取房间列表
  useEffect(() => {
    fetchRooms();
  }, [filter, pagination.limit, pagination.offset]);

  // 监听房间更新
  useEffect(() => {
    if (!socket) return;

    // 监听房间更新事件
    socket.on('roomUpdated', (data) => {
      if (data.roomId) {
        // 更新特定房间
        setRooms(prevRooms => 
          prevRooms.map(room => 
            room.roomId === data.roomId ? data.room : room
          )
        );
      } else {
        // 重新获取房间列表
        fetchRooms();
      }
    });

    // 监听房间创建成功
    socket.on('roomCreated', (data) => {
      setShowCreateModal(false);
      setNewRoomName('');
      setNewRoomMaxPlayers(4);
      fetchRooms();
    });

    // 监听加入房间结果
    socket.on('joinedRoom', (data) => {
      if (data.success) {
        navigate(`/room/${data.roomId}`);
      } else {
        setError(data.message || '加入房间失败');
      }
    });

    // 清理事件监听
    return () => {
      socket.off('roomUpdated');
      socket.off('roomCreated');
      socket.off('joinedRoom');
    };
  }, [socket, navigate]);

  // 创建房间
  const handleCreateRoom = async () => {
    // 验证房间名称
    const validation = validateRoomName(newRoomName);
    if (!validation.valid) {
      setError(validation.message);
      return;
    }

    setCreatingRoom(true);
    setError(null);

    try {
      const response = await apiClient.post('/api/rooms/create', {
        name: newRoomName,
        max_players: newRoomMaxPlayers
      });

      if (response.code === 200) {
        // 通过Socket通知服务器创建房间
        socket.emit('createRoom', {
          roomId: response.data.roomId,
          name: response.data.name,
          maxPlayers: response.data.maxPlayers
        });
      } else {
        setError(response.message || '创建房间失败');
      }
    } catch (err) {
      console.error('创建房间失败:', err);
      setError('创建房间失败，请稍后重试');
    } finally {
      setCreatingRoom(false);
    }
  };

  // 加入房间
  const handleJoinRoom = async (roomId) => {
    setError(null);

    try {
      const response = await apiClient.post('/api/rooms/join', {
        room_id: roomId
      });

      if (response.code === 200) {
        // 通过Socket通知服务器加入房间
        socket.emit('joinRoom', {
          roomId: roomId
        });
      } else {
        setError(response.message || '加入房间失败');
      }
