                <button
                  onClick={handleCreateRoom}
                  disabled={creatingRoom}
                  className="px-4 py-2 bg-blue-500 text-white rounded-lg hover:bg-blue-600 transition disabled:opacity-50"
                >
                  {creatingRoom ? '创建中...' : '创建房间'}
                </button>
              </div>
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default LobbyPage;

